def transform(grid):
    """Move every nonzero, non-2 connected object toward the 2-wall under gravity."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Locate the solid 2 wall and choose motion toward it.
    wall_rows = [r for r, row in enumerate(g) if row and all(v == 2 for v in row)]
    wall_cols = [c for c in range(w) if all(g[r][c] == 2 for r in range(h))]
    if wall_rows:
        direction = 1 if wall_rows[0] == 0 else -1
    elif wall_cols:
        direction = 1 if wall_cols[0] == 0 else -1
    else:
        direction = 1
    # Objects are 4-connected same-color components; move all movable components
    # synchronously one cell per tick until none can move.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and g[nr][nc] == color:
                        seen.add((nr,nc)); stack.append((nr,nc))
            objects.append((color, cells))
    while True:
        occupied = {p for _, cells in objects for p in cells}
        movable = []
        for i, (color, cells) in enumerate(objects):
            shifted = [(r+direction, c) if wall_rows else (r, c+direction) for r,c in cells]
            valid = True
            for nr,nc in shifted:
                if not (0 <= nr < h and 0 <= nc < w):
                    valid = False; break
                if g[nr][nc] == 2:
                    valid = False; break
                if (nr,nc) in occupied and (nr,nc) not in cells:
                    valid = False; break
            if valid:
                movable.append(i)
        if not movable:
            break
        # All pieces that can move at this tick advance together.
        moving = set(movable)
        for i in movable:
            color, cells = objects[i]
            for r,c in cells: g[r][c] = 0
        for i in movable:
            color, cells = objects[i]
            cells = [(r+direction, c) if wall_rows else (r, c+direction) for r,c in cells]
            objects[i] = (color, cells)
        for i in movable:
            color, cells = objects[i]
            for r,c in cells: g[r][c] = color
    return g
